import{_ as t,a,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"程序员英语 03：读懂文档中的条件与约束","description":"从默认行为、必要条件、例外与未知信息四个角度精读技术文档，并理解规范用语的边界。","frontmatter":{"title":"程序员英语 03：读懂文档中的条件与约束","description":"从默认行为、必要条件、例外与未知信息四个角度精读技术文档，并理解规范用语的边界。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"程序员英语","summary":"从默认行为、必要条件、例外与未知信息四个角度精读技术文档，并理解规范用语的边界。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary"},"next":{"text":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary"},"next":{"text":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search"}},"headers":[],"relativePath":"life/english/programmer/reading-docs.md","filePath":"life/english/programmer/reading-docs.md"}'),i={name:"life/english/programmer/reading-docs.md"};function n(l,e,s,d,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="程序员英语-03-读懂文档中的条件与约束" tabindex="-1">程序员英语 03：读懂文档中的条件与约束 <a class="header-anchor" href="#程序员英语-03-读懂文档中的条件与约束" aria-label="Permalink to &quot;程序员英语 03：读懂文档中的条件与约束&quot;">​</a></h1><p>技术文档阅读的结果应该是一组可以核对的判断。打开一页文档后，先确认产品、版本、平台和页面类型：教程里的简化示例，不一定列出了参考手册中的全部限制。</p><h2 id="用五个问题提取信息" tabindex="-1">用五个问题提取信息 <a class="header-anchor" href="#用五个问题提取信息" aria-label="Permalink to &quot;用五个问题提取信息&quot;">​</a></h2><p>下面是虚构批处理工具的说明，不代表某个现有产品：</p><blockquote><p>By default, the importer reads UTF-8 files and skips blank lines. When strict mode is enabled, a malformed record stops the import. Otherwise, the importer records the error and continues. The importer writes output only if at least one valid record is found. Existing output files are not overwritten unless <code>--replace</code> is set.</p></blockquote><table tabindex="0"><thead><tr><th>问题</th><th>原文证据</th><th>可得出的结论</th></tr></thead><tbody><tr><td>默认行为是什么？</td><td>by default、skips</td><td>默认按 UTF-8 读取并跳过空行</td></tr><tr><td>什么触发变化？</td><td>when strict mode is enabled</td><td>严格模式遇到格式错误会停止</td></tr><tr><td>否则会怎样？</td><td>otherwise</td><td>非严格模式记录该错误并继续</td></tr><tr><td>有什么必要条件？</td><td>only if、at least one</td><td>输出要求至少一条有效记录</td></tr><tr><td>有什么例外？</td><td>not ... unless</td><td>未设置替换选项时，不覆盖已有输出文件</td></tr></tbody></table><p>这张表仍没有回答：停止前已经写出的内容会回滚吗？错误记录存到哪里？默认是否开启严格模式？缺少信息就记录“未说明”，再找相关章节或做实验，不能把常见行为当成文档承诺。</p><h2 id="分清充分条件与必要条件" tabindex="-1">分清充分条件与必要条件 <a class="header-anchor" href="#分清充分条件与必要条件" aria-label="Permalink to &quot;分清充分条件与必要条件&quot;">​</a></h2><p><code>The tool writes output if a record is valid.</code> 表达“记录有效就输出”。<code>The tool writes output only if a record is valid.</code> 表达“输出必须以记录有效为前提”，并不排除权限不足等其他阻止输出的条件。</p><p>读 <code>unless</code> 可以先改成 <code>if not</code>：<code>Do not overwrite the file unless replacement is enabled.</code> 可理解为“如果没有启用替换，就不要覆盖”。它没有证明启用后一定成功覆盖，还可能存在权限等问题。</p><p>在代码里，这些差别会落到分支条件；可对照<a href="/life/math/programmer/logic-sets">程序员数学的逻辑篇</a>理解。</p><h2 id="规范中的-must、should、may" tabindex="-1">规范中的 MUST、SHOULD、MAY <a class="header-anchor" href="#规范中的-must、should、may" aria-label="Permalink to &quot;规范中的 MUST、SHOULD、MAY&quot;">​</a></h2><p>在明确采用 BCP 14 约定的规范中，<code>MUST</code> 表示必须满足，<code>MUST NOT</code> 表示禁止；<code>SHOULD</code> 表示有充分理由且理解后果时才可例外；<code>MAY</code> 表示允许选择。可核对 <a href="https://www.rfc-editor.org/rfc/rfc2119.html" target="_blank" rel="noopener noreferrer">RFC 2119</a>。</p><p><a href="https://www.rfc-editor.org/rfc/rfc8174.html" target="_blank" rel="noopener noreferrer">RFC 8174</a> 进一步明确了大写用法。不要把任何教程中小写的 <code>may</code> 都当成规范级许可，也不要因为一句话没有大写关键词就认定它没有要求；仍需阅读文档自己的约定和完整上下文。</p><h2 id="练习-把段落变成测试问题" tabindex="-1">练习：把段落变成测试问题 <a class="header-anchor" href="#练习-把段落变成测试问题" aria-label="Permalink to &quot;练习：把段落变成测试问题&quot;">​</a></h2><p>针对开头的 importer 说明，判断：</p><ol><li>严格模式下，第 5 行格式错误，第 6 行一定继续读取。</li><li>只有空行的输入，一定写出一个空结果文件。</li><li>已有输出文件且未传 <code>--replace</code>，允许直接覆盖。</li><li>非严格模式出现格式错误后，能否继续？输出一定成功吗？</li></ol><details class="details custom-block"><summary>查看答案与讲解</summary><ol><li>错。原文说格式错误停止导入。</li><li>错。原文把存在有效记录列为输出的必要条件。</li><li>错。覆盖已有文件必须满足替换选项条件。</li><li>能继续读取，因为 <code>otherwise ... continues</code>；但不能保证输出成功，文件权限、有效记录数量等条件仍可能阻止输出。</li></ol><p>可以据此设计“严格模式 + 错误记录”“全空行”“已有输出 + 无替换参数”三个检查场景。阅读产生了可验证的问题，才真正进入开发工作。</p></details><h2 id="一份可复用的阅读笔记" tabindex="-1">一份可复用的阅读笔记 <a class="header-anchor" href="#一份可复用的阅读笔记" aria-label="Permalink to &quot;一份可复用的阅读笔记&quot;">​</a></h2><p>记录四行即可：<code>Confirmed</code>（已确认）、<code>Conditions</code>（条件）、<code>Unknown</code>（未说明）、<code>Next check</code>（下一步核查）。例如：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Confirmed: Strict mode stops on a malformed record.</span></span>
<span class="line"><span>Conditions: Output requires at least one valid record.</span></span>
<span class="line"><span>Unknown: Whether earlier output is rolled back.</span></span>
<span class="line"><span>Next check: Read the section on partial imports.</span></span></code></pre></div><p>不要为了写得流畅，把 Unknown 改写成未经证实的结论。</p>`,22)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
